describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket",
      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 5000, costCents: 1000 },
    ]);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      expect(calc.computeShippingCents([makeLine("a", 1)], 1000)).toBe(0);
    });

    it("selects first bracket at boundary", () => {
      // 500g exactly → first bracket
      expect(
        calc.computeShippingCents([makeLine("a", 1, 500)], 1000),
      ).toBe(300);
    });

    it("selects second bracket just over first boundary", () => {
      // 501g → second bracket
      expect(
        calc.computeShippingCents([makeLine("a", 1, 501)], 1000),
      ).toBe(500);
    });

    it("selects second bracket at its boundary", () => {
      // 1000g exactly → second bracket
      expect(
        calc.computeShippingCents([makeLine("a", 1, 1000)], 1000),
      ).toBe(500);
    });

    it("selects third bracket for heavier items", () => {
      // 2000g → third bracket
      expect(
        calc.computeShippingCents([makeLine("a", 2, 1000)], 1000),
      ).toBe(1000);
    });

    it("uses heaviest bracket cost when no overflow configured", () => {
      // 6000g exceeds all brackets → last bracket cost
      expect(
        calc.computeShippingCents([makeLine("a", 6, 1000)], 1000),
      ).toBe(1000);
    });

    it("uses overflowCostCents when configured", () => {
      const calcWithOverflow = new WeightBasedShippingCalculator(
        [{ upToGrams: 1000, costCents: 500 }],
        2000,
      );
      expect(
        calcWithOverflow.computeShippingCents([makeLine("a", 2, 1000)], 1000),
      ).toBe(2000);
    });

    it("sorts brackets regardless of input order", () => {
      const unsorted = new WeightBasedShippingCalculator([
        { upToGrams: 5000, costCents: 1000 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ]);
      expect(
        unsorted.computeShippingCents([makeLine("a", 1, 500)], 1000),
      ).toBe(300);
    });

    it("sums weight across multiple lines", () => {
      // 2 items * 300g + 1 item * 200g = 800g → second bracket
      const lines: CartLine[] = [
        makeLine("a", 2, 300),
        makeLine("b", 1, 200),
      ];
      expect(calc.computeShippingCents(lines, 1000)).toBe(500);
    });
  });
});

