import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { Product } from "../src/product.ts";

const product = (id: string, price: number, weight?: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: price,
  weightGrams: weight,
});

describe("Cart", () => {
  describe("add", () => {
    it("adds a new product", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantities when adding same product twice", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 2);
      cart.add(product("a", 100), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 100), 0)).toThrow(RangeError);
      expect(() => cart.add(product("a", 100), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 100), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unit price", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 3);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity is set to 0", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 3);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product id", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("x", 1)).toThrow("not in the cart");
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 1);
      expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("empties the cart", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 1);
      cart.add(product("b", 200), 2);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns deep copy of lines", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0].product.id).toBe("a");
      expect(snap[0].quantity).toBe(2);
    });

    it("mutations to snapshot don't affect cart", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 2);
      const snap = cart.snapshot();
      (snap as any)[0].quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of price*qty", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 2);
      cart.add(product("b", 300), 1);
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(500);
    });

    it("applies discount, then tax on discounted subtotal", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const cart = new Cart({
        discountPolicy: discount,
        taxCalculator: tax,
      });
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();

      expect(totals.subtotalCents).toBe(1000);
      expect(totals.discountCents).toBe(200);
      // Tax is called with discounted subtotal (1000 - 200 = 800)
      expect(tax.computeTaxCents).toHaveBeenCalledWith(800, "US");
      expect(totals.taxCents).toBe(80);
    });

    it("clamps discount to [0, subtotal]", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(9999),
      };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(product("a", 500), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(500); // clamped to subtotal
    });

    it("clamps negative discount to 0", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(product("a", 500), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(0);
    });

    it("shipping receives lines and discounted subtotal", () => {
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(700),
      };
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(100),
      };
      const cart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
      });
      cart.add(product("a", 1000), 1);
      cart.totals();
      expect(shipping.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        900, // 1000 - 100
      );
    });

    it("totalCents = discountedSubtotal + tax + shipping", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 100,
      };
      const tax: TaxCalculator = {
        computeTaxCents: () => 50,
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: () => 200,
      };
      const cart = new Cart({
        discountPolicy: discount,
        taxCalculator: tax,
        shippingCalculator: shipping,
      });
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();
      // subtotal=1000, discount=100, discountedSub=900, tax=50, shipping=200
      expect(totals.totalCents).toBe(900 + 50 + 200);
    });

    it("empty cart has all zeros", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("uses custom region for tax", () => {
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator: tax, region: "FR" });
      cart.add(product("a", 1000), 1);
      cart.totals();
      expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
    });

    it("clamps negative tax to 0", () => {
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-50),
      };
      const cart = new Cart({ taxCalculator: tax });
      cart.add(product("a", 1000), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-50),
      };
      const cart = new Cart({ shippingCalculator: shipping });
      cart.add(product("a", 1000), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError, type PriceFetcher, type InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";
import type { Product } from "../src/product.ts";

const product = (id: string, price: number, weight?: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: price,
  weightGrams: weight,
});

describe("Cart.checkout()", () => {
  describe("without collaborators", () => {
    it("returns totals from sync pipeline", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.lines).toHaveLength(1);
    });
  });

  describe("with PriceFetcher", () => {
    it("refreshes prices before computing totals", async () => {
      const cart = new Cart();
      cart.add(product("a", 100), 1);
      cart.add(product("b", 200), 1);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockImplementation((id: string) =>
          Promise.resolve(id === "a" ? 500 : 600),
        ),
      };

      const result = await cart.checkout({ priceFetcher: fetcher });
      expect(result.totals.subtotalCents).toBe(1100); // 500 + 600
      expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
      expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("b");
    });

    it("propagates fetcher error", async () => {
      const cart = new Cart();
      cart.add(product("a", 100), 1);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
      };

      await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
        "price service down",
      );
    });
  });

  describe("with InventoryChecker", () => {
    it("passes when all items are available", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };

      const result = await cart.checkout({ inventoryChecker: checker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(checker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 0,
          reason: "out of stock",
        }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(2);
        expect(invErr.available).toBe(0);
        expect(invErr.message).toBe("out of stock");
      }
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 5);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(5);
        expect(invErr.available).toBe(3);
      }
    });

    it("first denial wins when multiple items fail", async () => {
      const cart = new Cart();
      cart.add(product("a", 100), 1);
      cart.add(product("b", 200), 1);

      const checker: InventoryChecker = {
        check: vi.fn().mockImplementation((id: string) => {
          if (id === "a") return Promise.resolve({ available: false, availableQuantity: 0 });
          return Promise.resolve({ available: true, availableQuantity: 10 });
        }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        expect((err as InventoryError).productId).toBe("a");
      }
    });
  });

  describe("with AsyncTaxRateProvider", () => {
    it("uses async tax rate for totals", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      // tax = 10% of 1000 = 100
      expect(result.totals.taxCents).toBe(100);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
    });

    it("applies async tax on discounted subtotal", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
      });
      cart.add(product("a", 1000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      // discount = 20% of 1000 = 200; discounted = 800; tax = 10% of 800 = 80
      expect(result.totals.discountCents).toBe(200);
      expect(result.totals.taxCents).toBe(80);
    });

    it("propagates async tax provider error", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });
  });

  describe("full pipeline with all collaborators", () => {
    it("refreshes prices, checks inventory, computes async tax + discount + shipping", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(500),
        region: "US-CA",
      });
      cart.add(product("a", 100), 2); // will be repriced to 1000 each

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1000),
      };

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
      };

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.0875),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // subtotal = 2 * 1000 = 2000
      expect(result.totals.subtotalCents).toBe(2000);
      // discount = 10% of 2000 = 200
      expect(result.totals.discountCents).toBe(200);
      // discounted = 1800; tax = 8.75% of 1800 = 157.5 → 157
      expect(result.totals.taxCents).toBe(157);
      // shipping = flat 500
      expect(result.totals.shippingCents).toBe(500);
      // total = 1800 + 157 + 500 = 2457
      expect(result.totals.totalCents).toBe(2457);

      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });
  });
});

