toolArgs.file_text:
import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { Product } from "../src/product.ts";

const product = (id: string, price: number, weight?: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: price,
  weightGrams: weight,
});

describe("Cart", () => {
  describe("add", () => {
    it("adds a new product", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantities when adding same product twice", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 2);
      cart.add(product("a", 100), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 100), 0)).toThrow(RangeError);
      expect(() => cart.add(product("a", 100), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 100), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unit price", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 3);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity is set to 0", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 3);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product id", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("x", 1)).toThrow("not in the cart");
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 1);
      expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("empties the cart", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 1);
      cart.add(product("b", 200), 2);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns deep copy of lines", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0].product.id).toBe("a");
      expect(snap[0].quantity).toBe(2);
    });

    it("mutations to snapshot don't affect cart", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 2);
      const snap = cart.snapshot();
      (snap as any)[0].quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of price*qty", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 2);
      cart.add(product("b", 300), 1);
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(500);
    });

    it("applies discount, then tax on discounted subtotal", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const cart = new Cart({
        discountPolicy: discount,
        taxCalculator: tax,
      });
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();

      expect(totals.subtotalCents).toBe(1000);
      expect(totals.discountCents).toBe(200);
      // Tax is called with discounted subtotal (1000 - 200 = 800)
      expect(tax.computeTaxCents).toHaveBeenCalledWith(800, "US");
      expect(totals.taxCents).toBe(80);
    });

    it("clamps discount to [0, subtotal]", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(9999),
      };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(product("a", 500), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(500); // clamped to subtotal
    });

    it("clamps negative discount to 0", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(product("a", 500), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(0);
    });

    it("shipping receives lines and discounted subtotal", () => {
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(700),
      };
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(100),
      };
      const cart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
      });
      cart.add(product("a", 1000), 1);
      cart.totals();
      expect(shipping.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        900, // 1000 - 100
      );
    });

    it("totalCents = discountedSubtotal + tax + shipping", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 100,
      };
      const tax: TaxCalculator = {
        computeTaxCents: () => 50,
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: () => 200,
      };
      const cart = new Cart({
        discountPolicy: discount,
        taxCalculator: tax,
        shippingCalculator: shipping,
      });
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();
      // subtotal=1000, discount=100, discountedSub=900, tax=50, shipping=200
      expect(totals.totalCents).toBe(900 + 50 + 200);
    });

    it("empty cart has all zeros", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("uses custom region for tax", () => {
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator: tax, region: "FR" });
      cart.add(product("a", 1000), 1);
      cart.totals();
      expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
    });

    it("clamps negative tax to 0", () => {
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-50),
      };
      const cart = new Cart({ taxCalculator: tax });
      cart.add(product("a", 1000), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-50),
      };
      const cart = new Cart({ shippingCalculator: shipping });
      cart.add(product("a", 1000), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });
  });
});

