import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError, type PriceFetcher, type InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";
import type { Product } from "../src/product.ts";

const product = (id: string, price: number, weight?: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: price,
  weightGrams: weight,
});

describe("Cart.checkout()", () => {
  describe("without collaborators", () => {
    it("returns totals from sync pipeline", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.lines).toHaveLength(1);
    });
  });

  describe("with PriceFetcher", () => {
    it("refreshes prices before computing totals", async () => {
      const cart = new Cart();
      cart.add(product("a", 100), 1);
      cart.add(product("b", 200), 1);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockImplementation((id: string) =>
          Promise.resolve(id === "a" ? 500 : 600),
        ),
      };

      const result = await cart.checkout({ priceFetcher: fetcher });
      expect(result.totals.subtotalCents).toBe(1100); // 500 + 600
      expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
      expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("b");
    });

    it("propagates fetcher error", async () => {
      const cart = new Cart();
      cart.add(product("a", 100), 1);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
      };

      await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
        "price service down",
      );
    });
  });

  describe("with InventoryChecker", () => {
    it("passes when all items are available", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };

      const result = await cart.checkout({ inventoryChecker: checker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(checker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 0,
          reason: "out of stock",
        }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(2);
        expect(invErr.available).toBe(0);
        expect(invErr.message).toBe("out of stock");
      }
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 5);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(5);
        expect(invErr.available).toBe(3);
      }
    });

    it("first denial wins when multiple items fail", async () => {
      const cart = new Cart();
      cart.add(product("a", 100), 1);
      cart.add(product("b", 200), 1);

      const checker: InventoryChecker = {
        check: vi.fn().mockImplementation((id: string) => {
          if (id === "a") return Promise.resolve({ available: false, availableQuantity: 0 });
          return Promise.resolve({ available: true, availableQuantity: 10 });
        }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        expect((err as InventoryError).productId).toBe("a");
      }
    });
  });

  describe("with AsyncTaxRateProvider", () => {
    it("uses async tax rate for totals", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      // tax = 10% of 1000 = 100
      expect(result.totals.taxCents).toBe(100);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
    });

    it("applies async tax on discounted subtotal", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
      });
      cart.add(product("a", 1000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      // discount = 20% of 1000 = 200; discounted = 800; tax = 10% of 800 = 80
      expect(result.totals.discountCents).toBe(200);
      expect(result.totals.taxCents).toBe(80);
    });

    it("propagates async tax provider error", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });
  });

  describe("full pipeline with all collaborators", () => {
    it("refreshes prices, checks inventory, computes async tax + discount + shipping", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(500),
        region: "US-CA",
      });
      cart.add(product("a", 100), 2); // will be repriced to 1000 each

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1000),
      };

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
      };

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.0875),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // subtotal = 2 * 1000 = 2000
      expect(result.totals.subtotalCents).toBe(2000);
      // discount = 10% of 2000 = 200
      expect(result.totals.discountCents).toBe(200);
      // discounted = 1800; tax = 8.75% of 1800 = 157.5 → 157
      expect(result.totals.taxCents).toBe(157);
      // shipping = flat 500
      expect(result.totals.shippingCents).toBe(500);
      // total = 1800 + 157 + 500 = 2457
      expect(result.totals.totalCents).toBe(2457);

      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });
  });
});

